mapper.select:
SELECT log_id, request_id, operator_id, operator_name, module, operation, target_type,
       target_id, target_name, request_method, request_url, request_params, response_result,
       ip_address, user_agent, status, error_msg, cost_time, created_at, remark
FROM sys_operation_log


        AND module = #{module}


        AND operation = #{operation}


        AND operator_id = #{operatorId}


        AND target_id = #{targetId}


        AND status = #{status}


ORDER BY created_at DESC, log_id DESC

SELECT COUNT(*) FROM sys_operation_log
WHERE module = #{module} AND operation = #{operation}
  AND (#{targetId} IS NULL OR target_id = #{targetId})
